(()=>{'use strict';const R=window.FLIGHT_RECORDS,api=window.flightMissionAPI,el=id=>document.getElementById(id);let selected='',renderKey='',lastPlanId='';
function reveal(id){const target=el(id);if(!target)return;for(let p=target;p;p=p.parentElement)if(p.tagName==='DETAILS')p.open=true;const section=target.querySelector('.field-section');if(section)section.open=true;target.scrollIntoView({block:'start',behavior:'instant'});}
const panel=document.createElement('section');panel.className='record-manager';panel.id='recordmanager';panel.setAttribute('aria-label','Flight record management');panel.innerHTML=`<div class="record-current"><span class="eyebrow">Current pre-flight editor</span><h3 id="currentflightreference"></h3><p id="currentflightidentity"></p><p id="currentsavestate" role="status"></p></div><div id="managerrecovery" class="classhelp" hidden><p id="managerrecoverytext"></p><div class="inline"><button id="managerrecover" type="button" class="btn">Recover previous draft</button><button id="managerfresh" type="button" class="btn">Keep saved records; start a fresh draft</button></div></div><p><b>One flight, one reference.</b> Save a plan today, resume that same flight tomorrow, then record take-off/landing and save its post-flight debrief. Reusing setup for another take-off creates a different reference.</p><div class="inline"><button id="newblankflight" class="btn" type="button">Create blank flight</button><button id="openflightdebrief" class="btn" type="button">Open current flight / debrief</button></div><details id="savedflightmanager"><summary>Saved flights · resume, review or reuse setup</summary><label><span class="label">Find flight · project, title or reference</span><input id="flightrecordsearch" type="search" placeholder="Search saved flights"></label><label><span class="label">Saved flight record · all phases grouped</span><select id="flightrecordselect"></select></label><p id="selectedflightstatus" role="status"></p><div class="record-actions-grid"><button id="resumeplannedflight" class="btn primary" type="button">Resume this planned flight</button><button id="openrecorddebrief" class="btn" type="button">Open flight / post-flight debrief</button><button id="newfromsavedflight" class="btn" type="button">Create new flight using this setup</button><button id="exportcompleteflight" class="btn" type="button">Download this complete flight · JSON</button><button id="reportcompleteflight" class="btn" type="button">Download this complete flight · HTML/PDF</button><button id="importcompleteflight" class="btn" type="button">Import flight record or backup</button></div><p class="hint"><b>Resume</b> retains the flight reference and planned date/time, but clears live checks/readings for renewal. <b>Create new</b> preserves reusable setup under a different reference. Saved history is never rewritten. You can finish earlier debriefs after starting plans for other flights.</p><div id="completeflightview"></div></details><details><summary>What saves, and when?</summary><ol><li><b>Save pre-flight briefing:</b> retains a dated revision under the current flight reference, even if planning is incomplete. It does not save post-flight editor changes.</li><li><b>Record take-off:</b> saves and links the launch briefing automatically. Flight events and landing save immediately.</li><li><b>Save post-flight debrief:</b> appends a revision to the selected flight. Unfinished post-flight edits have a separate browser-local recovery draft.</li><li><b>Download all app data:</b> backs up every saved phase, profiles, batteries and recovery drafts. A single-flight download contains only that selected flight's records, not the whole inventory.</li></ol><p>No need to finish a debrief before planning another flight. A recorded airborne flight must first be landed or have its outcome resolved. Records stay on this browser/device until exported; they do not synchronise automatically.</p></details><p id="recordmanagerstatus" class="hint" role="status"></p>`;
el('missioncard').querySelector('.body').prepend(panel);
el('missionprefill').hidden=true;el('saveflight').textContent='Save pre-flight briefing';
el('saveflight').nextElementSibling.textContent='Saves only the current pre-flight briefing as a revision under this flight reference. You can save today and resume tomorrow. Flight events save automatically; post-flight work has its own save button.';
const copyHelp=el('copycurrentmission').closest('.inline').nextElementSibling;if(copyHelp)copyHelp.textContent='Creates a different flight reference using the current setup. A named current plan is saved first. To continue the same planned flight later, use Resume in Saved flights.';
function groups(){return R.groups(api.records(),window.flightLifecycleSnapshot?.().sorties||[]);}
function chosen(){return groups().find(g=>g.id===selected)||null;}
function say(text){el('recordmanagerstatus').textContent=text;el('recordmanagerstatus').classList.toggle('action-notice',!!text);}
function planAction(action,success){const result=action();if(!result){say(api.recovery?.()?'Previous draft is waiting. Choose Recover previous draft or Start fresh in the highlighted panel above before creating/resuming another flight.':api.message()||'Action could not complete. Check the current flight and recovery choices above.');if(api.recovery?.())el('managerrecovery').scrollIntoView({block:'center'});else if(!el('projecttitle').value.trim()||!el('missiontitle').value.trim())el(!el('projecttitle').value.trim()?'projecttitle':'missiontitle').focus();return false;}say(success);reveal('missioncard');return true;}
function guard(action){const done=window.flightLifecycleAPI.guardLeave(()=>{try{action();render(true);}catch(error){say(error.message);}});if(!done){say('Finish the pending flight/debrief action shown below before switching records.');reveal('postflightcard');}return done;}
function download(name,value,type){const url=URL.createObjectURL(new Blob([value],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function draftsFor(g){const state=window.flightLifecycleAPI.draftSnapshot(),ids=new Set(g.sorties.map(s=>s.id));const drafts=Object.fromEntries(Object.entries(state.drafts).filter(([id])=>ids.has(id)));return Object.keys(drafts).length?{version:1,drafts}:null;}
function options(g){return{appVersion:window.FLIGHTDESK_BUILD?.appVersion,drafts:draftsFor(g)};}
function openDebrief(g){if(!g?.sorties.length){say('This is a planned flight. Resume it to continue pre-flight work; flight/debrief sections appear after a recorded take-off or plan outcome.');return;}const s=g.sorties.find(s=>s.phase==='AIRBORNE')||g.sorties.at(-1);if(window.flightLifecycleAPI.selectSortie(s.id)){reveal(s.phase==='AIRBORNE'?'flightcard':'postflightcard');say('Opened '+g.reference+' · '+g.missionTitle+'. The pre-flight editor remains separately identified above.');}else reveal('postflightcard');}
el('newblankflight').onclick=()=>guard(()=>{if(planAction(()=>api.newBlank(),'Blank flight created. Enter its project and flight title, then save the briefing.'))selected='';});
el('copycurrentmission').onclick=()=>guard(()=>{const id=api.currentFlightId(),existing=groups().find(g=>g.id===id);if(api.recovery?.()){planAction(()=>false,'');return;}const record=existing?.sorties.length?existing.latest:api.saveBriefing();if(!record){say(api.message());reveal('missioncard');return;}if(planAction(()=>api.newFromRecord(record),'New flight created with a different reference. Earlier records are retained.'))selected='';});
el('openflightdebrief').onclick=()=>openDebrief(groups().find(g=>g.id===api.currentFlightId()));
el('resumeplannedflight').onclick=()=>guard(()=>{const g=chosen();if(g?.canResume&&planAction(()=>api.resume(g.latest),'Resumed the same flight '+g.reference+'. Renew time-sensitive information before take-off.'))selected=g.id;});
el('newfromsavedflight').onclick=()=>guard(()=>{const g=chosen();if(g?.latest&&planAction(()=>api.newFromRecord(g.latest),'Setup copied to a new flight with a different reference. Review its title and planned date/time.'))selected='';});
el('managerrecover').onclick=()=>guard(()=>{el('recoverdraft').click();if(api.recovery?.()){say(el('draftstatus').textContent);return;}say('Previous draft recovered under its original reference. You can now save it, resume another saved plan or create a different flight.');render(true);});
el('managerfresh').onclick=()=>guard(()=>{el('dismissdraft').click();say('Started a fresh draft. Your saved briefing/flight/debrief records are retained. Choose the saved setup and press Create new flight again.');render(true);});
el('openrecorddebrief').onclick=()=>openDebrief(chosen());
el('exportcompleteflight').onclick=()=>{try{const g=chosen();if(!g)throw Error('Select a saved flight');const data=R.bundle(g,options(g));download('flightdesk-'+g.reference+'-complete.json',JSON.stringify(data,null,2),'application/json');say('Downloaded all saved phases for '+g.reference+'. Includes unfinished debrief recovery draft if present; it is labelled separately.');}catch(e){say(e.message);}};
el('reportcompleteflight').onclick=()=>{try{const g=chosen();if(!g)throw Error('Select a saved flight');download('flightdesk-'+g.reference+'-complete.html',R.reportHTML(g,options(g)),'text/html;charset=utf-8');say('Complete flight report downloaded. Open it and use Print / Save as PDF. Keep JSON for restoration.');}catch(e){say(e.message);}};
el('importcompleteflight').onclick=()=>el('restoreall').click();
el('flightrecordselect').onchange=()=>{selected=el('flightrecordselect').value;render(true);};el('flightrecordsearch').oninput=()=>render(true);
function currentStatus(){const recovery=api.recovery?.();el('managerrecovery').hidden=!recovery;if(recovery)el('managerrecoverytext').textContent='Previous draft available: '+(recovery.projectTitle||'Untitled project')+' / '+(recovery.missionTitle||'Untitled flight')+' · '+recovery.savedAt+'. Choose Recover or Start fresh before switching. Saved flights are unaffected.';const current=api.current(),g=groups().find(g=>g.id===current.missionId),locked=!!g?.sorties.length;el('currentflightreference').textContent=R.reference(current.missionId)+' · '+(current.missionTitle||'Untitled flight');el('currentflightidentity').textContent=(current.projectTitle||'Project not named')+' · '+(g?R.statusLabel(g.status):'Draft · not yet saved as a briefing');el('currentsavestate').dataset.state=locked?'archived':api.hasUnsavedChanges()?'unsaved':'saved';el('currentsavestate').textContent=locked?'Pre-flight history is archived for this flight. Open its flight/debrief, or create another flight from the setup.':g?(api.hasUnsavedChanges()?'Pre-flight changes need a saved revision. ':'Saved pre-flight revision. ')+'Last saved briefing: '+g.latest.savedAt+' · '+g.briefings.length+' revision(s). Current work autosaves as a recoverable draft; save a briefing revision when ready.':'Not yet in saved flights. Add project/title and Save pre-flight briefing; incomplete plans can be saved.';el('saveflight').disabled=locked;const bottom=el('saveflightbottom');if(bottom)bottom.disabled=locked;el('openflightdebrief').disabled=!locked;}
function render(force=false){currentStatus();const all=groups(),filter=el('flightrecordsearch').value.trim().toLowerCase(),list=all.filter(g=>(g.reference+' '+g.id+' '+g.projectTitle+' '+g.missionTitle).toLowerCase().includes(filter));const currentId=api.currentFlightId();if(currentId!==lastPlanId){lastPlanId=currentId;if(all.some(g=>g.id===currentId))selected=currentId;}if(!list.some(g=>g.id===selected))selected=list[0]?.id||'';const key=JSON.stringify([list.map(g=>[g.id,g.status,g.lastActivity,g.briefings.length,g.sorties.map(s=>[s.phase,s.debriefs.length,s.events.length])]),selected,filter]);if(!force&&key===renderKey)return;renderKey=key;const select=el('flightrecordselect');select.replaceChildren();if(!list.length){const option=document.createElement('option');option.value='';option.textContent=filter?'No matching saved flights':'No saved flights yet';select.append(option);}for(const g of list){const option=document.createElement('option');option.value=g.id;option.textContent=g.reference+' · '+g.projectTitle+' / '+g.missionTitle+' · '+R.statusLabel(g.status);select.append(option);}select.value=selected;const g=list.find(g=>g.id===selected);el('resumeplannedflight').disabled=!g?.canResume;el('resumeplannedflight').title=g?.canResume?'Continue this same unflown plan':'Only an unflown plan can be resumed. Open its flight/debrief or create another flight.';el('openrecorddebrief').disabled=!g?.sorties.length;for(const id of ['newfromsavedflight','exportcompleteflight','reportcompleteflight'])el(id).disabled=!g;el('completeflightview').replaceChildren();el('selectedflightstatus').textContent=g?g.reference+' · '+R.statusLabel(g.status)+' · '+g.briefings.length+' briefing revision(s), '+g.sorties.reduce((n,s)=>n+s.events.length,0)+' event(s), '+g.sorties.reduce((n,s)=>n+s.debriefs.length,0)+' post-flight revision(s).':'Save a pre-flight briefing to create a saved flight. No flight is selected.';if(!g)return;
const identity=document.createElement('p');identity.className='hint';identity.textContent='Full flight ID: '+g.id+(g.legacy?' · Legacy record grouped using existing identifiers; no history has been rewritten.':'');el('completeflightview').append(identity);const phases=document.createElement('div');phases.className='record-phase-summary';for(const [name,value]of [['Pre-flight',g.briefings.length?g.briefings.length+' saved revision(s)':'Launch briefing retained with flight'],['Flight',g.sorties.length?g.sorties.map(s=>R.statusLabel(s.phase)).join('; '):'Not yet flown'],['Post-flight',g.sorties.some(s=>s.debriefs.length)?g.sorties.reduce((n,s)=>n+s.debriefs.length,0)+' saved revision(s)':'Not yet saved']]){const box=document.createElement('div'),strong=document.createElement('strong'),p=document.createElement('p');strong.textContent=name;p.textContent=value;box.append(strong,p);phases.append(box);}el('completeflightview').append(phases);
const history=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Briefing revision history · recorded evidence';history.append(summary);for(const [i,b]of g.briefings.entries()){const d=document.createElement('details'),s=document.createElement('summary'),pre=document.createElement('pre');s.textContent='Revision '+(i+1)+' · '+b.savedAt+' · '+(b.readiness?.status||'not recorded')+' at save';pre.textContent=JSON.stringify(b,null,2);d.append(s,pre);history.append(d);}el('completeflightview').append(history);if(g.sorties.length>1){const p=document.createElement('p');p.className='hint';p.textContent='Older data contains multiple sorties under this identity. Each is retained separately. Select the exact sortie in Post-flight to edit its debrief; new flights now require distinct references.';el('completeflightview').append(p);}}
window.addEventListener('flightdesk:briefingsaved',e=>{selected=e.detail.flightId;render(true);});for(const name of ['flightdesk:flightlog','flightdesk:planningchanged','flightdesk:restored'])window.addEventListener(name,()=>render(true));window.addEventListener('flightdesk:sortieselected',e=>{const group=groups().find(g=>g.sorties.some(s=>s.id===e.detail.id));if(group)selected=group.id;render(true);});window.addEventListener('flightdesk:decision',()=>currentStatus());document.addEventListener('input',e=>{if(['projecttitle','missiontitle'].includes(e.target.id))currentStatus();});
render(true);
})();
